<?php
function beheerRekentabelMagOpenen(): bool { if (empty($GLOBALS['ingelogd'])) return false; if (!empty($GLOBALS['isMaster'])) return true; return in_array('rekentabel', (array)($GLOBALS['toegestaneTabs'] ?? []), true); }
function beheerRekentabelBewaakLegacyPost(): void { if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST' || (string)($_POST['formulier'] ?? '') !== 'rekentabel') return; $_POST['formulier']=''; if(function_exists('schrijfLog')) schrijfLog($GLOBALS['logBestand'],$GLOBALS['huidigeGebruiker'],'legacy_rekentabel_geblokkeerd','rekentabel'); }
function beheerRekentabelStartOutputFilter(): void { ob_start(function($html){ if(!is_string($html))return $html; if(beheerRekentabelMagOpenen())$html=preg_replace('~<button\s+type="button"\s+class="menu-item"\s+data-tab="rekentabel">.*?</button>~is','<a class="menu-item menu-item-link" style="display:block;text-decoration:none" href="rekentabel.php">* Rekentabel</a>',$html,1)??$html; if(stripos($html,'</head>')!==false)$html=preg_replace('~</head>~i','<style>#tab-rekentabel{display:none!important}</style></head>',$html,1)??$html; return $html;}); }
beheerRekentabelBewaakLegacyPost(); beheerRekentabelStartOutputFilter();
